import{_ as e,o as r,c as a,ag as d}from"./chunks/framework.Aev9KvMf.js";const i=JSON.parse('{"title":"标签要变什么 · GB 28050-2025 新旧对比（2027 实施预告）","description":"GB 28050 新旧对比预告：强制标示从 1+4 扩为 1+6（新增糖、饱和脂肪）、强制\\"盐油糖\\"提示语、2027 年 3 月 16 日实施，逐条链接官方问答。","frontmatter":{"title":"标签要变什么 · GB 28050-2025 新旧对比（2027 实施预告）","issuer":"国家卫生健康委（标准问答）","source_tier":"一级来源","version":"GB 28050—2011 → GB 28050—2025","published":"2025-09","source_url":"https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml","status":"新版已发布（2027-03-16 实施）","tags":["国标","营养标签","新版对比","行动清单"],"type":"国标科普","reviewed":false,"description":"GB 28050 新旧对比预告：强制标示从 1+4 扩为 1+6（新增糖、饱和脂肪）、强制\\"盐油糖\\"提示语、2027 年 3 月 16 日实施，逐条链接官方问答。"},"headers":[],"relativePath":"standards/gb28050-2025-preview.md","filePath":"standards/gb28050-2025-preview.md"}'),s={name:"standards/gb28050-2025-preview.md"};function o(n,t,c,h,l,f){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="标签要变什么-·-gb-28050-2025-新旧对比-2027-实施预告" tabindex="-1">标签要变什么 · GB 28050-2025 新旧对比（2027 实施预告） <a class="header-anchor" href="#标签要变什么-·-gb-28050-2025-新旧对比-2027-实施预告" aria-label="Permalink to &quot;标签要变什么 · GB 28050-2025 新旧对比（2027 实施预告）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据国家卫健委官方问答整理，尚未逐条对照原文校验；校验通过前请以官方问答与标准原文为准。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页内容<strong>整理自国家卫健委官方问答</strong>（一级来源），逐条可点击溯源。本站不构成诊疗建议。</p></div><blockquote><p><strong>出处</strong>：《食品安全国家标准 预包装食品营养标签通则》（GB 28050-2025）问答，国家卫生健康委（<a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">官方问答页</a>）。下文&quot;出处&quot;链接指向本站镜像的<a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">官方问答 PDF 不可用时的问答页</a>。</p></blockquote><h2 id="速览卡-给家庭的三个变化" tabindex="-1">速览卡（给家庭的三个变化） <a class="header-anchor" href="#速览卡-给家庭的三个变化" aria-label="Permalink to &quot;速览卡（给家庭的三个变化）&quot;">​</a></h2><ol><li><strong>营养成分表从&quot;1+4&quot;变&quot;1+6&quot;</strong>：强制标示新增<strong>糖</strong>和<strong>饱和脂肪</strong>——控糖、控饱和脂肪的家庭以后直接读表。</li><li><strong>营养成分表下方强制出现提示语</strong>：&quot;儿童青少年应避免过量摄入盐油糖&quot;。</li><li><strong>2027 年 3 月 16 日实施</strong>：实施日后生产的食品按新标准标示；之前生产的可在保质期内继续销售。（<a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">问答·实施日期</a>）</li></ol><h2 id="新旧对比表" tabindex="-1">新旧对比表 <a class="header-anchor" href="#新旧对比表" aria-label="Permalink to &quot;新旧对比表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>现行 GB 28050—2011</th><th>新版 GB 28050—2025</th><th>出处</th></tr></thead><tbody><tr><td>强制标示</td><td>能量 + 蛋白质、脂肪、碳水化合物、钠（&quot;1+4&quot;）</td><td>能量 + 蛋白质、脂肪、<strong>饱和脂肪（或饱和脂肪酸）</strong>、碳水、<strong>糖</strong>、钠（&quot;1+6&quot;）</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">问答·强制标示</a></td></tr><tr><td>提示语</td><td>无</td><td>营养成分表下方<strong>强制标示&quot;儿童青少年应避免过量摄入盐油糖&quot;</strong></td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">问答·提示语</a></td></tr><tr><td>&quot;糖&quot;的定义</td><td>未强制标示</td><td>单糖和双糖之和，明确限定为葡萄糖、果糖、蔗糖、麦芽糖、乳糖之和</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">问答·糖</a></td></tr><tr><td>糖的 NRV%</td><td>—</td><td>糖无 NRV 规定，NRV% 可空白、斜线或横线表达</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">问答·NRV%</a></td></tr><tr><td>过渡期</td><td>—</td><td>实施日（2027-03-16）后生产的食品按新标准；此前生产的保质期内继续销售</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">问答·实施日期</a></td></tr><tr><td>豁免规则</td><td>有豁免范围</td><td>豁免原则不变（含量不稳定/包装过小/食用量小）；有营养信息、强化剂、营养声称等情形仍须强制标示</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">问答·豁免</a></td></tr></tbody></table><h2 id="给家庭的行动清单" tabindex="-1">给家庭的行动清单 <a class="header-anchor" href="#给家庭的行动清单" aria-label="Permalink to &quot;给家庭的行动清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>现在买食品：仍按 2011 版读&quot;1+4&quot;，控糖家庭先用配料表判断糖（配料表递减排位）</td><td><a href="/SageRelay/standards/gb28050-nutrition-label.html">GB 28050 词条</a></td></tr><tr><td>2027 年后买食品：直接读表中新增的<strong>糖</strong>和<strong>饱和脂肪</strong>两行</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">问答·强制标示</a></td></tr><tr><td>给孩子选零食：认准营养成分表下方&quot;儿童青少年应避免过量摄入盐油糖&quot;提示语所在表</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">问答·提示语</a></td></tr><tr><td>【本站提示】新旧包装过渡期内，同一食品可能两种标签并存——看懂&quot;1+4&quot;和&quot;1+6&quot;两种表都不慌</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">问答·实施日期</a></td></tr></tbody></table><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>版本</td><td>GB 28050—2011（现行）→ GB 28050—2025（2027-03-16 实施）</td></tr><tr><td>归口</td><td>国家卫生健康委（食品安全国家标准）</td></tr><tr><td>出处</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">官方问答页</a> · <a href="https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=28050" target="_blank" rel="noreferrer">标准查询（全文公开系统）</a></td></tr></tbody></table>',12)])])}const p=e(s,[["render",o]]);export{i as __pageData,p as default};
